#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

static char *prefix(const void *storage, long long length) {
    const unsigned char *bytes = storage;
    const char *digits = "0123456789abcdef";
    char *result = malloc((size_t)length * 2 + 1);
    for (long long i = 0; i < length; i++) {
        result[i * 2] = digits[bytes[i] >> 4];
        result[i * 2 + 1] = digits[bytes[i] & 15];
    }
    result[length * 2] = 0;
    return result;
}
char *ref_int(long long value, long long count) { return prefix(&value, count); }
char *ref_long(long long value, long long count) { return prefix(&value, count); }
char *ref_int32(int32_t value, long long count) { return prefix(&value, count); }
char *ref_uint(uint64_t value, long long count) { return prefix(&value, count); }
char *ref_uint32(uint32_t value, long long count) { return prefix(&value, count); }
char *ref_float(float value, long long count) { return prefix(&value, count); }
char *ref_double(double value, long long count) { return prefix(&value, count); }
char *ref_char(char first, char second) { char values[2] = {first, second}; return prefix(values, 2); }
char *ref_bool(bool first, bool second) { bool values[2] = {first, second}; return prefix(values, 2); }
float make_float(double value) { return (float)value; }

